<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="js/live-search.js"></script><script>function enlazarEdicionMecanicos(){document.querySelectorAll('.editar-mecanico').forEach(function(b){b.addEventListener('click',function(){['id','nombre','telefono','especialidad'].forEach(function(c){var e=document.getElementById('editar-'+c);if(e)e.value=b.dataset[c]||'';});});});}enlazarEdicionMecanicos();document.addEventListener('ag:live-search-updated',enlazarEdicionMecanicos);</script></main></body></html>
